def haversine(lat1, lon1, lat2, lon2):
    r=6371
    p1,p2=math.radians(lat1),math.radians(lat2)
    dp=math.radians(lat2-lat1); dl=math.radians(lon2-lon1)
    a=math.sin(dp/2)**2+math.cos(p1)*math.cos(p2)*math.sin(dl/2)**2
    return 2*r*math.asin(math.sqrt(a))

def normalize_country(s):
    s=clean_arabic_text(s)
    aliases={"امريكا":"الولايات المتحده", "usa":"الولايات المتحده", "امريكا":"الولايات المتحده", "اسبانيا":"اسبانيا", "السعوديه":"السعوديه", "الامارات":"الامارات"}
    return aliases.get(s,s)

class CountryGame:
    def __init__(self, channel_id, host_id):
        self.channel_id=channel_id; self.host_id=host_id; self.round=0; self.max_rounds=6; self.country=None; self.answers={}; self.running=False; self.message=None
    def pick(self):
        # remove duplicate Jordan entries from accidental duplicate source row
        self.country=random.choice(list({x[0]:x for x in COUNTRIES}.values()))
        self.answers={}
    async def run_round(self, channel):
        self.round += 1; self.pick(); self.running=True
        name,code,lat,lon=self.country
        embed=discord.Embed(title=f"🌍 خمن الدولة • الجولة {self.round}/6", description="**__ اكتب اسم الدولة في الشات خلال 10 ثوانٍ. كل رسالة باسم دولة تعتبر مشاركة. __**", color=pink_color())
        embed.set_image(url=f"https://flagcdn.com/w640/{code}.png")
        self.message=await channel.send(embed=embed)
        def check(m): return m.channel.id==self.channel_id and not m.author.bot
        try:
            collected=await bot.wait_for("message", timeout=10, check=check)
        except asyncio.TimeoutError:
            collected=None
        # Collect every answer received during the 10-second window by using history.
        cutoff=datetime.datetime.now(datetime.timezone.utc)-datetime.timedelta(seconds=10)
        try:
            history=[m async for m in channel.history(limit=100, after=cutoff) if not m.author.bot]
        except Exception:
            history=[collected] if collected else []
        for m in history:
            ans=normalize_country(m.content)
            self.answers[m.author.id]=(m.author.display_name, ans)
        lines=[]
        for uid,(display,ans) in self.answers.items():
            target=next((c for c in COUNTRIES if normalize_country(c[0])==ans), None)
            if not target:
                continue
            dist=haversine(target[2],target[3],lat,lon)
            points=50 if dist < 1 else max(1, int(round(50*(1-dist/20000))))
            if normalize_country(target[0])==normalize_country(name): points=50
            lines.append((points,display,target[0],dist))
        lines.sort(reverse=True,key=lambda x:x[0])
        result=f"**__ الدولة: {name} __**\n"
        if lines:
            result += "\n".join(f"🎯 {d}: `{p}` نقطة • إجابة: {a} • بُعد: `{dist:.0f} كم`" for p,d,a,dist in lines[:10])
        else:
            result += "\nلم يتم تسجيل إجابة دولة صالحة."
        await channel.send(embed=discord.Embed(title="🏁 نتيجة الجولة", description=result, color=pink_color()))
        self.running=False
    async def run(self, channel):
        for _ in range(self.max_rounds):
            await self.run_round(channel)
            await asyncio.sleep(1)
        await channel.send(bold_msg("انتهت لعبة خمن الدولة بعد 6 جولات!", "🏆"))

active_country_games={}
@bot.command(name="خمن_الدولة", aliases=["خمن_الدوله"])
async def guess_country(ctx):
    if ctx.channel.id in active_country_games:
        await ctx.send(bold_msg("هناك لعبة خمن الدولة تعمل في هذا الشات.", "⚠️")); return
    game=CountryGame(ctx.channel.id,ctx.author.id); active_country_games[ctx.channel.id]=game
    try: await game.run(ctx.channel)
    finally: active_country_games.pop(ctx.channel.id,None)

# ==============================================================================
# Arabic Wordle
# ==============================================================================
WORDLE_WORDS=["كتاب","صباح","ملعب","لاعب","سريع","جميل","طريق","مدينة","مدرسة","صديق","قهوة","شجرة","هاتف","سيرفر","فريق","كرسي","مفتاح","سيارة","حديقة","رسالة","مكتبة","بطولة","جمهور","مباراة","نتيجة","مشجع","لاعبون","رئيسي","عالمي","مغربي"]
WORDLE_WORDS=[w for w in WORDLE_WORDS if len(w)==5]
WORDLE_LEN=5

def wordle_feedback(secret, guess):
    # Works for the five-character dictionary; repeated letters are handled with counts.
    secret=list(secret); guess=list(guess); result=["⬜"]*len(guess)
    counts={}
    for ch in secret: counts[ch]=counts.get(ch,0)+1
    for i,ch in enumerate(guess):
        if i<len(secret) and ch==secret[i]: result[i]="🟩"; counts[ch]-=1
    for i,ch in enumerate(guess):
        if result[i]=="🟩": continue
        if counts.get(ch,0)>0: result[i]="🟨"; counts[ch]-=1
    return "".join(result)

class WordleGame:
    def __init__(self,channel,author): self.channel=channel; self.author=author; self.secret=random.choice(WORDLE_WORDS); self.rows=[]
    def board(self):
        return "\n".join(self.rows+["⬜"*WORDLE_LEN]*(6-len(self.rows)))

@bot.command(name="wordle", aliases=["وردل"])
async def wordle(ctx):
    game=WordleGame(ctx.channel.id,ctx.author.id)
    embed=discord.Embed(title="🟩 Wordle عربي", description="**__ اكتب كلمة من 5 أحرف في الشات. لديك 6 محاولات. 🟩 صحيح • 🟨 موجود • ⬜ غير موجود __**\n\n"+game.board(), color=pink_color())
    msg=await ctx.send(embed=embed)
    def check(m): return m.channel.id==ctx.channel.id and m.author.id==ctx.author.id and len(clean_arabic_text(m.content).replace(" ",""))==WORDLE_LEN
    for _ in range(6):
        try: m=await bot.wait_for("message",timeout=60,check=check)
        except asyncio.TimeoutError: break
        guess=clean_arabic_text(m.content).replace(" ","")
        game.rows.append(wordle_feedback(game.secret,guess))
        embed.description="**__ اكتب كلمة من 5 أحرف. 🟩 صحيح • 🟨 موجود • ⬜ غير موجود __**\n\n"+game.board()
        if guess==game.secret:
            embed.description += f"\n\n**__ 🎉 فزت! الكلمة: {game.secret} __**"; await msg.edit(embed=embed); return
        await msg.edit(embed=embed)
    embed.description += f"\n\n**__ انتهت المحاولات. الكلمة كانت: {game.secret} __**"
    await msg.edit(embed=embed)

