class XOView(discord.ui.View):
    def __init__(self,author):
        super().__init__(timeout=180); self.author=author; self.board=[" "]*9; self.done=False
    def winner(self):
        for a,b,c in [(0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6)]:
            if self.board[a]!=" " and self.board[a]==self.board[b]==self.board[c]: return self.board[a]
        return "draw" if " " not in self.board else None
    def render(self): return "\n".join(" | ".join(self.board[i:i+3]) for i in range(0,9,3))
    async def play(self,interaction,index):
        if interaction.user.id!=self.author.id: await interaction.response.send_message(bold_msg("هذه اللعبة ليست لك.","🔒"),ephemeral=True); return
        if self.done or self.board[index]!=" ": await interaction.response.send_message(bold_msg("هذه الخانة غير متاحة.","⚠️"),ephemeral=True); return
        self.board[index]="❌"; w=self.winner()
        if not w:
            empty=[i for i,x in enumerate(self.board) if x==" "]
            if empty: self.board[random.choice(empty)]="⭕"
            w=self.winner()
        if w: self.done=True
        embed=discord.Embed(title="⭕❌ XO VS BOT",description=f"```\n{self.render()}\n```\n"+("**__ تعادل! __**" if w=="draw" else f"**__ الفائز: {'أنت' if w=='❌' else 'البوت'} __**" if w else "**__ دورك. __**"),color=pink_color())
        for child in self.children: child.disabled=self.done or self.board[child.row*3+child.col]!=" "
        await interaction.response.edit_message(embed=embed,view=self)
    def add_buttons(self):
        for i in range(9):
            btn=discord.ui.Button(label=str(i+1),style=discord.ButtonStyle.secondary,row=i//3)
            btn.row=i//3; btn.col=i%3
            async def callback(interaction,idx=i): await self.play(interaction,idx)
            btn.callback=callback; self.add_item(btn)

@bot.command(name="xo", aliases=["اكس_او"])
async def xo(ctx):
    view=XOView(ctx.author); view.add_buttons()
    await ctx.send(embed=discord.Embed(title="⭕❌ XO VS BOT",description="**__ اضغط رقم الخانة للعب. أنت ❌ والبوت ⭕ __**\n```\n 1 | 2 | 3\n 4 | 5 | 6\n 7 | 8 | 9\n```",color=pink_color()),view=view)

