# ==============================================================================
# Hide & Seek - 25 buttons
# ==============================================================================
class HideSeekGridView(discord.ui.View):
    def __init__(self, game):
        super().__init__(timeout=300)
        self.game=game
        for i in range(25):
            b=discord.ui.Button(label=str(i+1), style=discord.ButtonStyle.secondary, row=i//5)
            b.index=i
            async def cb(interaction, idx=i):
                await self.game.choose(interaction, idx)
            b.callback=cb
            self.add_item(b)

class HideSeekGame:
    def __init__(self,ctx):
        self.ctx=ctx; self.players={}; self.hider_slots={}; self.found=set(); self.running=False; self.grid_view=None
    async def join(self,interaction):
        if self.running:
            await interaction.response.send_message(bold_msg("بدأت اللعبة بالفعل.","⚠️"),ephemeral=True); return
        if interaction.user.id in self.players:
            await interaction.response.send_message(bold_msg("أنت مشارك بالفعل.","ℹ️"),ephemeral=True); return
        self.players[interaction.user.id]=interaction.user.display_name
        await interaction.response.send_message(bold_msg("تم تسجيل مشاركتك.","✅"),ephemeral=True)
    async def choose(self,interaction,idx):
        if not self.running:
            await interaction.response.send_message(bold_msg("لم تبدأ مرحلة الاختباء بعد.","⚠️"),ephemeral=True); return
        if interaction.user.id not in self.players:
            await interaction.response.send_message(bold_msg("اضغط مشاركة أولًا.","⚠️"),ephemeral=True); return
        if interaction.user.id in self.hider_slots:
            await interaction.response.send_message(bold_msg("اخترت مكانًا بالفعل.","⚠️"),ephemeral=True); return
        self.hider_slots[interaction.user.id]=idx
        await interaction.response.send_message(bold_msg(f"تم إخفاؤك في الرقم {idx+1}. لا يظهر اختيارك للآخرين.","🫣"),ephemeral=True)
    async def start(self,interaction):
        if interaction.user.id!=self.ctx.author.id:
            await interaction.response.send_message(bold_msg("فقط صاحب اللعبة يستطيع بدءها.","🔒"),ephemeral=True); return
        if len(self.players)<2:
            await interaction.response.send_message(bold_msg("تحتاج اللعبة إلى لاعبين على الأقل.","⚠️"),ephemeral=True); return
        self.running=True; self.grid_view=HideSeekGridView(self)
        embed=discord.Embed(title="🫣 Hide & Seek • مرحلة الاختباء",description="**__ الآن اختاروا واحدًا من الـ25 رقمًا. لديكم 20 ثانية. اختيار المكان يرسل لك تأكيدًا خاصًا ولا يظهر للآخرين. __**",color=pink_color())
        await interaction.response.edit_message(embed=embed,view=self.grid_view)
        await asyncio.sleep(20); await self.search()
    async def search(self):
        alive=set(self.hider_slots.keys())
        if len(alive)<=1:
            if alive:
                uid=next(iter(alive)); await self.ctx.channel.send(bold_msg(f"الفائز هو **{self.players[uid]}**! 🏆","🎉"))
            else:
                await self.ctx.channel.send(bold_msg("لم يختر أحد مكانًا للاختباء.","⚠️"))
            self.running=False; return
        slots=list(range(25)); random.shuffle(slots)
        occupied={}
        for uid,slot in self.hider_slots.items(): occupied.setdefault(slot,[]).append(uid)
        for slot in slots:
            if len(alive)<=1: break
            found_here=[uid for uid in occupied.get(slot,[]) if uid in alive]
            if found_here:
                names=[]
                for uid in found_here:
                    alive.remove(uid); self.found.add(uid); names.append(self.players[uid])
                await self.ctx.channel.send(bold_msg(f"البوت ضغط الرقم `{slot+1}` ووجد: **{', '.join(names)}** 💥","🔎"))
            else:
                await self.ctx.channel.send(bold_msg(f"البوت ضغط الرقم `{slot+1}` ولم يجد أحدًا. 🫣","❌"))
            await asyncio.sleep(1)
        if alive:
            winner=next(iter(alive)); await self.ctx.channel.send(bold_msg(f"الفائز الأخير هو **{self.players[winner]}**! 🏆","🎉"))
        self.running=False
        if self.grid_view:
            for child in self.grid_view.children: child.disabled=True

class HideSeekLobbyView(discord.ui.View):
    def __init__(self,game): super().__init__(timeout=120); self.game=game
    @discord.ui.button(label="مشاركة",emoji="🙋",style=discord.ButtonStyle.success)
    async def join(self,interaction,button): await self.game.join(interaction)
    @discord.ui.button(label="ابدأ اللعبة",emoji="🎮",style=discord.ButtonStyle.primary)
    async def start(self,interaction,button): await self.game.start(interaction)

@bot.command(name="غميمه")
async def hide_and_seek(ctx):
    game=HideSeekGame(ctx)
    embed=discord.Embed(title="🫣 Hide & Seek",description="**__ لعبة اختباء من 25 خانة. اضغط مشاركة للدخول، ثم عند البدء اختَر رقمًا للاختباء. البوت سيضغط أرقامًا عشوائية حتى يبقى آخر لاعب حي. __**",color=pink_color())
    file=image_file()
    if file: embed.set_image(url=image_attachment_url())
    await ctx.send(embed=embed,view=HideSeekLobbyView(game),**({"file": file} if file else {}))

